mapper.select:
INSERT INTO public.payments (
    users_id
) VALUES (
    (SELECT id FROM auth.users u WHERE u.email = #{email})
) RETURNING invoice_no

mapper.update:
UPDATE public.payments
SET payment_type = #{paymentType}
WHERE invoice_no = #{invoiceNo}

UPDATE public.payments
SET payment_id = #{paymentId}, payment_amount = #{paymentAmount}
WHERE invoice_no = #{invoiceNo}
